SET NAMES utf8mb4;

-- KVKK aydinlatma metnine FIRMA REHBERI bolumu eklendi (17 Eyl 2026).
--
-- Eksik gercekti: sitedeki en buyuk kisisel veri isleme faaliyeti — 1.300+
-- komisyoncu/sogut hava/nakliye kaydinin kamuya acik katalogdan derlenmesi —
-- aydinlatma metninde HIC gecmiyordu. Metinde komisyoncu, firma rehberi veya
-- kaynak katalog kelimesi yoktu.
--
-- Eklenen 3. bolum: kaynak, kapsam (tuzel kisi / gercek kisi ayrimi), hukuki
-- sebep (m.5/2-d alenilestirme + m.5/2-f mesru menfaat), KULLANILMADIGI
-- amaclar (pazarlama/ticari elektronik ileti/reklam hedef kitlesi yok, liste
-- satilmaz) ve duzeltme/kaldirma yolu. 3-8 arasi bolumler 4-9'a kaydirildi.
-- Toplama yontemi ve saklama bolumlerine de firma rehberi satiri eklendi.
--
-- Icerik HEX yazilir: uzun HTML'de tirnak/ters boluyu kacisi ve Turkce karakter
-- bozulmasi riski kalmasin (bkz. daha once yasanan "Tu00fcm Haller" vakasi).

UPDATE custom_pages_i18n
SET content = UNHEX('')
WHERE locale = 'tr' AND slug = 'kvkk';
